    "why_template": "城市里看不到的星星，夜空会替你说情话。多年以后，TA 可能忘了那晚的风，但不会忘了头顶的银河——那是你们一起看过的宇宙。",
    "best_scenarios": "无光污染的郊外星空营地，选流星雨爆发期（避开满月）效果最佳。",
    "unsuitable_scenarios": "天气差、满月、对方怕冷或不喜欢户外时不适合。",
    "purchase_or_booking_tip": "价格因营地和装备不定，预订前先询价；出发前查当年流星雨爆发时间（如8月英仙座、12月双子座），避开满月夜，提前订营地。",
    "ritual_tip": "抵达后先一起搭帐篷，天黑点马灯、裹同一条毯子看银河；数到流星记得一起许愿。",
    "pairing_ideas": "带星座APP认星座、热可可、拍立得记录星空下的合影。",
